import onnx,numpy as np
from onnx import numpy_helper as nh
def load(p):
    m=onnx.load(p); return {t.name:nh.to_array(t).astype(np.float64) for t in m.graph.initializer}
A=load('/nets/net1.onnx');B=load('/nets/net2.onnx')
z=np.load('box.npz');lo,hi=z['lo'],z['hi'];act=np.where(hi>lo)[0]
def f(P,X):
    for k in range(3): X=np.maximum(X@P['W%d'%k].T+P['B%d'%k],0)
    return X@P['W3'].T+P['B3']
def g(v):
    X=np.tile(lo,(len(v),1)); X[:,act]=v; return (f(A,X)-f(B,X))[:,3]
best=-1
rng=np.random.default_rng(1)
for r in range(300):
    v=(rng.random(15)>0.5).astype(float)
    cur=g(v[None])[0]
    imp=True
    while imp:
        imp=False
        for i in range(15):
            for val in np.linspace(0,1,11):
                w=v.copy();w[i]=val;s=g(w[None])[0]
                if s>cur+1e-9: cur=s;v=w;imp=True
    if cur>best: best=cur;bv=v
print(best,bv)
